// Core relocation loop during dynamic loading
void apply_relocations(RelocationTable R_tab, void* load_base) {
    // R_tab holds entries defining necessary address fixups
    for (RelocationEntry R : R_tab) {
        uint64_t target_addr = resolve_symbol(R.symbol_idx);
        void* patch_site = load_base + R.offset;
        uint64_t final_value;

        // Example: Absolute relocation (R_X86_64_64)
        final_value = target_addr + R.addend;

        // Patch the memory location
        *(uint64_t*)patch_site = final_value;
    }
}

